time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "bd4a0a93-3146-46cb-d711-abd5c0db0459", "sort_order": 0, "title": "Hawa Mahal", "description": "Whispers of history in wind.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "1ea03f5c-ca98-c0d6-44ca-96bdc0f304c3", "sort_order": 1, "title": "City Palace", "description": "Royal legacy, echoes of sovereignty.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "804a0e99-83d3-cca4-20cf-d2dc26ce6c3c", "sort_order": 2, "title": "Observatory / Jantar Mantar", "description": "Celestial marvels, antique astronomy.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "728803b8-23e1-ffaa-62ea-e688711598be", "sort_order": 3, "title": "Jal Mahal", "description": "Peaceful waters, regal reflection.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "81c33007-f2d5-a3f0-b944-7da5f3591412", "sort_order": 4, "title": "Amer Fort", "description": "Strength in stone, tales unfold.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "22f85478-6191-be78-52fc-703615c9f6f9", "sort_order": 5, "title": "Nahargarh Fort", "description": "Sentinel of Jaipur, royal views.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "7f689bb4-c422-f04a-9c72-9f5db075d108", "day_number": 3, "day_title": "Jaipur - Ajmer - Pushkar", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, proceed to visit Ajmer and Pushkar, famous for their religious significance and as popular pilgrimage centers. You are going to visit a spiritual hub; Ajmer is home to the revered Ajmer Sharif Dargah. Experience the city''s rich religious heritage, bustling markets, and serene Ana Sagar Lake.\nPushkar is renowned for its sacred Pushkar Lake and the Brahma Temple, Pushkar is a vibrant pilgrimage site. Enjoy the lively Pushkar Camel Fair and the town''s bohemian vibe.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Pushkar", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "4e33eddb-c9bb-5e58-5ea2-5f962e0c73bc", "sort_order": 0, "title": "Dargah of Khwaja Muin-ud-din Chisti at Ajmer", "description": "Sufi mysticism, spiritual sanctuary.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "b58ad81a-0604-9e9b-6c87-2c988f925af6", "sort_order": 1, "title": "Lord Brahma Temple at Pushkar", "description": "Sacred sanctum, divine presence.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "dda3ae64-53fe-364e-89fe-9a560f0fe6d8", "day_number": 4, "day_title": "Pushkar - Chittorgarh - Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, journey towards Chittorgarh to explore its magnificent fortresses, temples, towers, and palaces. Steeped in heroic tales, Chittorgarh Fort is a symbol of Rajput valor and sacrifice. Explore the massive fort complex, historic palaces, and intricate temples.\nLater, continue towards the beautiful Lake City, Udaipur. Udaipur also known as the \"City of Lakes,\" it enchants with its serene waters, grand palaces, and romantic atmosphere. Upon arrival, check into the hotel and enjoy an amazing boat ride over Lake Pichola.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Chittorgarh", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "878c9bee-a76b-f823-ecea-6ec451dd65e1", "day_number": 5, "day_title": "Udaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After having breakfast at hotel, explore the enchanting Lake City with its cultural and historical landmarks:", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null]